import {LEVELS,WORLDS,MAX_LEVEL,buildLevel,levelById} from './levels.js';
import {runnerState,stepRunner,botInput} from './simulation.js';
import {progress} from './physics.js';
import {createProfileStore,OUTFITS} from './profile.js';
import {GameView} from './visuals.js';
const $=id=>document.getElementById(id),escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=localStorage}catch{storage={getItem(){throw Error()},setItem(){throw Error()}}}
const profile=createProfileStore(storage);let level=profile.get().selected,mode='lobby',previousMode='race',online=false,socket=null,myId=null,network=null,connectTimer,netElapsed=0,lastNetMessage=0,lastResult=false;
let player,bots=[],time=0,worldTime=0,countTime=0,accumulator=0,last=performance.now(),toastTime=0,hitFlash=0,queuedJump=false,queuedDive=false,inputPrevJump=false,frameCount=0,performanceTime=0;
const keys=new Set();let view,audioCtx;
try{view=new GameView($('game'))}catch(error){$('loading').innerHTML='<h2>3D graphics could not start.</h2><p>Enable hardware acceleration in your browser, then reload.</p>';throw error}
view.quality(profile.get().quality);view.load(level);
const ownAppearance=()=>{const p=profile.get(),o=OUTFITS.find(o=>o.id===p.outfit)||OUTFITS[0];return {id:'you',name:p.name,color:o.color,outfit:o.id,isBot:false}};
function formatTime(seconds,decimal=false){seconds=Math.max(0,Number(seconds)||0);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds)%60).padStart(2,'0')}${decimal?'.'+Math.floor(seconds%1*10):''}`}
function tone(f=500,d=.1,type='sine'){if(!profile.get().sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(f,audioCtx.currentTime);g.gain.setValueAtTime(.05,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}
function toast(text){$('race-message').textContent=text;$('race-message').style.opacity=1;toastTime=2}
function clearInput(){keys.clear();queuedJump=false;queuedDive=false}
function modal(html,{wide=false,closable=true}={}){$('modal').classList.toggle('wide',wide);$('modal-content').innerHTML=html;$('close-modal').hidden=!closable;if(!$('modal').open)$('modal').showModal()}
function closeModal(){if(mode==='paused'){mode=previousMode;last=performance.now()}$('modal').close()}
function resetRun(){player={...runnerState(1),...ownAppearance()};bots=Array.from({length:15},(_,i)=>({...runnerState(i+2),id:'bot-'+i,name:['Rio','Skye','Jett','Milo','Luna','Rex','Remi','Zara'][i%8],color:OUTFITS[i%3].color,outfit:OUTFITS[i%3].id,isBot:true,speed:7.9+(i%5)*.22+Math.min(.8,level*.016),lane:(i%3-1)*6,seed:i*.9}));time=0;worldTime=0;accumulator=0;lastResult=false;clearInput();view.clearRunners();view.load(level);$('progress-fill').style.width='0%';syncHUD();}
function syncLobby(){const p=profile.get(),l=levelById(level),o=OUTFITS.find(o=>o.id===p.outfit)||OUTFITS[0],complete=Object.keys(p.medals).filter(k=>p.medals[k]>0).length;document.documentElement.style.setProperty('--world-color','#'+l.theme.sky.toString(16));$('world-name').textContent=l.world.toUpperCase();$('course-name').textContent=l.name;$('level-number').textContent=String(level).padStart(2,'0');$('distance').textContent=l.distance.toLocaleString();$('hazard-count').textContent=l.hazardCount;$('gold-target').textContent=formatTime(l.gold);$('difficulty').textContent='●'.repeat(l.difficulty)+'○'.repeat(5-l.difficulty);$('wallet').textContent=p.coins.toLocaleString();$('xp').textContent=p.xp.toLocaleString();$('completed').textContent=complete;$('tour-fill').style.width=complete/50*100+'%';$('medal-total').textContent=Object.values(p.medals).reduce((a,b)=>a+b,0);$('runner-name').textContent=o.name.toUpperCase();$('runner-description').textContent=o.description;$('guest-label').textContent=p.name;$('player-rank').textContent=p.xp>15000?'WORLD TOUR LEGEND':p.xp>5000?'TRAILBLAZER':p.xp>1500?'RISING STAR':'ROOKIE RUNNER';$('play').innerHTML=(p.medals[level]?'BEAT YOUR BEST':'CONTINUE THE TOUR')+' <span>↗</span>';$('world-chapters').innerHTML=WORLDS.map((w,i)=>`<button class="world-chapter ${i===l.worldIndex?'active':''}" data-world="${i}" aria-label="Explore ${w.name}"><span class="world-dot">${p.unlocked<i*10+1?'⌁':String(i+1).padStart(2,'0')}</span><small>${w.name}</small></button>`).join('');document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>showMap(Number(b.dataset.world)));}
function syncHUD(){const l=levelById(level),c=buildLevel(level);$('race-level').textContent='LEVEL '+String(level).padStart(2,'0');$('race-world').textContent=l.world.toUpperCase();$('race-name').textContent=l.name;$('target-time').textContent='GOLD · '+formatTime(l.gold);$('timer').textContent=formatTime(time,true);$('checkpoint').textContent=`Checkpoint ${(player?.cp||0)+1} / ${c.checkpoints.length}`;$('remaining').textContent=Math.ceil(Math.max(0,l.distance-(4-(player?.z||4)))).toLocaleString()+' m to go';$('race-coins').textContent='● '+(player?.coins||0);$('progress-fill').style.width=progress(player?.z||4,level)*100+'%';const others=online?(network?.players||[]):[player,...bots];const position=player?.rank||1+others.filter(b=>b.id!==player?.id&&(b.finished||b.z<(player?.z||0))).length;$('position').innerHTML=position+'<small> / '+Math.max(1,others.length)+'</small>';$('pace').innerHTML=(mode==='race'&&!player?.finished?Math.round((player?.boost>0?14.7:10.5)*(readInput().dx||readInput().dz?1:0)):0)+'<small> m/s</small>'}
function showRaceUI(){$('lobby').hidden=true;$('hud').hidden=false;document.body.classList.add('racing');$('touch').hidden=!matchMedia('(pointer:coarse)').matches;}
function disconnect(){online=false;clearTimeout(connectTimer);if(socket){socket.onclose=null;socket.onerror=null;socket.close();socket=null}network=null;myId=null;$('online-status').hidden=true;}
function lobby(){disconnect();mode='lobby';$('modal').close();$('countdown').hidden=true;$('level-intro').hidden=true;$('lobby').hidden=false;$('hud').hidden=true;$('touch').hidden=true;document.body.classList.remove('racing');resetRun();syncLobby()}
function intro(nextLevel=level,isOnline=false){level=levelById(nextLevel).id;profile.update({selected:level});syncLobby();const l=levelById(level);modal(`<span class="pill">${l.world.toUpperCase()} · ${l.tag}</span><h2>Level ${String(level).padStart(2,'0')}</h2><h3>${l.name}</h3><p>${l.distance.toLocaleString()} metres. ${l.hazardCount} obstacles.<br>Reach the finish. Your result appears instantly.</p><div class="result-stats"><div><strong>${formatTime(l.gold)}</strong><span>GOLD TARGET</span></div><div><strong>${l.difficulty}/5</strong><span>DIFFICULTY</span></div><div><strong>${buildLevel(level).checkpoints.length}</strong><span>CHECKPOINTS</span></div></div><button id="start-level" class="primary-button">${isOnline?'FIND A LIVE RACE':'LET’S RUN'} <span>↗</span></button>`);$('start-level').onclick=()=>isOnline?joinOnline(level):startSolo()}
function tutorial(after){modal('<span class="pill">BEFORE YOUR FIRST RUN</span><h2>You’ve got this.</h2><div class="tutorial-steps"><p><b>Move with WASD or arrow keys.</b><br>Touch controls appear on phones.</p><p><b>Space to jump. Shift to dive.</b><br>Jump the gaps; dive for a little extra distance.</p><p><b>Coins are yours to collect.</b><br>Hit checkpoint flags to save your place. Green pads boost your pace.</p><p><b>Finish to unlock your next level.</b><br>Chase faster times for bronze, silver, and gold medals.</p></div><button id="tutorial-go" class="primary-button">I’M READY <span>↗</span></button>');$('tutorial-go').onclick=()=>{profile.update({tutorial:true});after()}}
function startSolo(){disconnect();$('modal').close();resetRun();mode='countdown';countTime=3;showRaceUI();$('countdown').hidden=false;$('countdown').textContent='3';$('level-intro').hidden=false;$('level-intro').textContent=`LEVEL ${level} / 50 · ${levelById(level).name.toUpperCase()}`;tone(440)}
function finish(win,{onlineFinish=false}={}){if(lastResult)return;lastResult=true;const wasOnline=online||onlineFinish;const resultTime=player.finishTime||time;const rank=player.rank||1+bots.filter(b=>b.finished).length;const reward=profile.record(level,resultTime,win,{coins:player.coins,rank,falls:player.falls});const completedLevel=level;disconnect();mode='results';clearInput();$('touch').hidden=true;$('countdown').hidden=true;$('level-intro').hidden=true;const medalNames=['','BRONZE','SILVER','GOLD'];const next=level<MAX_LEVEL?levelById(level+1):null;modal(`<div class="result-medal ${win?['','bronze','silver',''][reward.medal]:'failed'}">${win?'★':'↻'}</div><span class="pill">${win?medalNames[reward.medal]+' MEDAL':'TIME’S UP'} · LEVEL ${String(level).padStart(2,'0')}</span><h2>${win?(level===50?'World Tour complete.':'Finish line. Fresh start.'):'One more run?'}</h2><div class="result-time">${formatTime(resultTime,true)}</div><div class="result-best">${reward.newBest?'NEW PERSONAL BEST':win?'LEVEL COMPLETE':'YOUR CHECKPOINTS ARE READY FOR ANOTHER TRY'}</div><div class="result-stats"><div><strong>${rank}<small> / 16</small></strong><span>FINISH POSITION</span></div><div><strong>${player.coins}</strong><span>COINS COLLECTED</span></div><div><strong>${player.falls}</strong><span>TUMBLES</span></div></div><div class="reward-line"><span>+${reward.reward} COINS</span><span>+${reward.xp} XP</span>${win&&player.falls===0?'<span>CLEAN RUN ✓</span>':''}</div>${reward.newOutfit?`<p>New runner unlocked: <b>${reward.newOutfit.name}</b></p>`:''}${win&&next?`<div class="next-preview"><small>NEXT UP · ${next.world.toUpperCase()}</small><b>Level ${next.id} — ${next.name}</b><p>${next.distance.toLocaleString()} m · ${next.hazardCount} obstacles</p></div>`:''}<button id="next-level" class="primary-button">${win&&next?'NEXT LEVEL':win?'EXPLORE THE TOUR':'TRY AGAIN'} <span>↗</span></button><button id="retry-level" class="secondary-button">${win?'Replay this level':'Back to lobby'}</button><button id="result-home" class="secondary-button">World Tour map</button>`,{closable:true});$('next-level').onclick=()=>{if(win&&!next){lobby();showMap(4);return}level=win?completedLevel+1:completedLevel;profile.update({selected:level});wasOnline?joinOnline(level):startSolo()};$('retry-level').onclick=()=>{if(!win){lobby();return}level=completedLevel;wasOnline?joinOnline(level):startSolo()};$('result-home').onclick=()=>{lobby();showMap(Math.floor((level-1)/10))};if(win){view.burst(player.x,player.y,player.z);tone(660,.2);setTimeout(()=>tone(880,.25),180)}else tone(190,.3);syncLobby()}
function showMap(worldIndex=levelById(level).worldIndex){if(mode!=='lobby')lobby();const p=profile.get(),world=WORLDS[worldIndex];modal(`<span class="mini-label">YOUR NEXT ADVENTURE</span><h2>50 reasons to keep running.</h2><div class="map-tabs">${WORLDS.map((w,i)=>`<button class="map-tab ${i===worldIndex?'active':''}" data-tab="${i}">${String(i+1).padStart(2,'0')} ${w.name}</button>`).join('')}</div><div class="map-world-header"><h3>${world.name}</h3><span>Levels ${worldIndex*10+1}–${worldIndex*10+10}</span></div><div class="level-grid">${LEVELS.slice(worldIndex*10,worldIndex*10+10).map(l=>`<button class="level-card ${l.id===level?'active':''}" data-level="${l.id}" ${l.id>p.unlocked?'disabled':''}><span class="level-num">${String(l.id).padStart(2,'0')}</span><span class="stars">${l.id>p.unlocked?'⌁':'★'.repeat(p.medals[l.id]||0)}</span><b>${l.name}</b><small>${l.distance.toLocaleString()} m · ${l.hazardCount} obstacles</small></button>`).join('')}</div><p class="map-footer">Finish a level to unlock the next. Earn up to three medal stars per level. Your progress saves in this browser.</p>`,{wide:true});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showMap(Number(b.dataset.tab)));document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=Number(b.dataset.level);profile.update({selected:level});resetRun();syncLobby();intro(level)})}
function showCrew(){if(mode!=='lobby')lobby();const p=profile.get();modal(`<span class="mini-label">YOUR STYLE. YOUR RUN.</span><h2>Meet the crew.</h2><p>Finish levels to unlock new runners. Every runner has the same speed and jump ability.</p><div class="crew-grid">${OUTFITS.map((o,i)=>`<button class="crew-card ${p.outfit===o.id?'selected':''}" data-outfit="${o.id}" ${p.unlocked<o.unlock?'disabled':''}><span class="crew-symbol" style="--crew-color:${o.color}">${['↗','✦','⚡','★'][i]}</span><b>${o.name}</b><small>${o.description}</small><small>${p.unlocked<o.unlock?'Unlock at Level '+o.unlock:p.outfit===o.id?'EQUIPPED':'READY TO RUN'}</small></button>`).join('')}</div>`,{wide:true});document.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>{profile.update({outfit:b.dataset.outfit});resetRun();syncLobby();showCrew();tone(600,.07)})}
function showProfile(){modal('<span class="mini-label">NICE TO MEET YOU</span><h2>Your runner profile.</h2><div class="form-row"><label for="guest-name">DISPLAY NAME</label><input id="guest-name" maxlength="20" autocomplete="nickname"></div><p>Your chosen name is visible to players in your live race. Progress and personal bests stay in this browser.</p><button id="save-name" class="primary-button">SAVE PROFILE <span>✓</span></button>');$('guest-name').value=profile.get().name;$('save-name').onclick=()=>{profile.update({name:$('guest-name').value.trim()||'Guest Runner'});player.name=profile.get().name;syncLobby();closeModal()}}
function showSettings(){if(mode==='race'&&!online){previousMode=mode;mode='paused'}const p=profile.get();modal(`<h2>Make yourself comfortable.</h2><div class="form-row"><label for="sound-setting">SOUND EFFECTS</label><select id="sound-setting"><option value="on" ${p.sound?'selected':''}>On</option><option value="off" ${!p.sound?'selected':''}>Off</option></select></div><div class="form-row"><label for="quality-setting">GRAPHICS</label><select id="quality-setting"><option value="auto" ${p.quality==='auto'?'selected':''}>Auto — balanced quality</option><option value="low" ${p.quality==='low'?'selected':''}>Performance — fewer shadows</option></select></div><p>Guest progress is saved separately in each browser profile. People sharing one browser profile share its save. Clearing browser data removes progress.</p><p>${profile.isPersistent()?'Your save is active.':'Storage is unavailable. This visit’s progress cannot persist.'}</p><button id="save-settings" class="primary-button">DONE <span>✓</span></button><button id="reset-save" class="secondary-button">Reset this browser’s progress</button>`);$('save-settings').onclick=()=>{profile.update({sound:$('sound-setting').value==='on',quality:$('quality-setting').value});view.quality(profile.get().quality);closeModal()};$('reset-save').onclick=()=>{modal('<h2>Start fresh?</h2><p>This permanently removes the medals, coins, personal bests, and unlocked levels saved in this browser.</p><button id="confirm-reset" class="primary-button">RESET MY PROGRESS <span>↻</span></button><button id="cancel-reset" class="secondary-button">Keep my progress</button>');$('confirm-reset').onclick=()=>{profile.reset();location.href=location.pathname};$('cancel-reset').onclick=closeModal}}
function showHelp(){if(mode==='race'&&!online){previousMode=mode;mode='paused'}modal('<span class="pill">LEARN THE MOVES</span><h2>A little timing goes a long way.</h2><div class="help-grid"><div><kbd>W A S D / ARROWS</kbd>Move</div><div><kbd>SPACE</kbd>Jump</div><div><kbd>SHIFT</kbd>Dive in the air</div><div><kbd>ESC</kbd>Race menu</div></div><p>Jump over low barriers and gaps. Dodge moving hammers and rollers. Green pads give you a speed boost. Flags save your checkpoint.</p><p>Finish any level to unlock the next. Beat the target time for a gold medal. Online results appear as soon as you cross the finish.</p><button id="help-done" class="primary-button">GOT IT <span>↗</span></button>');$('help-done').onclick=closeModal}
function pause(){if(!['race','countdown','paused'].includes(mode))return;if(mode==='paused'){closeModal();return}clearInput();if(!online){previousMode=mode;mode='paused'}modal(`<span class="pill">${online?'LIVE RACE':'TAKE A BREATHER'}</span><h2>${online?'The race is still on.':'Ready when you are.'}</h2><p>${online?'Other runners keep racing while this menu is open.':'Your clock is paused.'}</p><button id="resume" class="primary-button">BACK TO THE RACE <span>↗</span></button><button id="quit" class="secondary-button">Leave race</button>`);$('resume').onclick=closeModal;$('quit').onclick=lobby}
function readInput(){if($('modal').open||!['race','countdown'].includes(mode))return {dx:0,dz:0};return {dx:Number(keys.has('KeyD')||keys.has('ArrowRight'))-Number(keys.has('KeyA')||keys.has('ArrowLeft')),dz:Number(keys.has('KeyS')||keys.has('ArrowDown'))-Number(keys.has('KeyW')||keys.has('ArrowUp'))}}
function soloStep(dt){time+=dt;worldTime+=dt;const input={...readInput(),jump:queuedJump,dive:queuedDive};queuedJump=false;queuedDive=false;const events=stepRunner(player,input,dt,worldTime,level);player.moving=!!(input.dx||input.dz);for(const b of bots)if(!b.finished){const e=stepRunner(b,botInput(b,worldTime,level),dt,worldTime,level);if(e.includes('finish')){b.rank=1+bots.filter(other=>other!==b&&other.finished).length;b.finishTime=time}}if(events.includes('jump'))tone(450,.08);if(events.includes('coin'))tone(1000,.05);if(events.includes('hit')){hitFlash=.8;tone(170,.12,'triangle')}if(events.includes('checkpoint')){toast('CHECKPOINT SAVED');tone(720,.12)}if(events.includes('fall'))toast('BACK ON YOUR FEET');if(events.includes('boost')){toast('PICK UP THE PACE');tone(600,.12)}if(events.includes('finish')){player.rank=1+bots.filter(b=>b.finished).length;player.finishTime=time;finish(true);return}if(time>=levelById(level).seconds)finish(false)}
function joinOnline(nextLevel=level,room){disconnect();lastNetMessage=0;netElapsed=0;level=levelById(nextLevel).id;profile.update({selected:level});resetRun();online=true;mode='waiting';showRaceUI();$('touch').hidden=true;$('online-status').hidden=false;$('online-status').textContent='CONNECTING TO LIVE RACE';modal('<span class="pill">LIVE MATCHMAKING</span><h2>Finding your starting line.</h2><p>Connecting to the race server…</p><button id="cancel-queue" class="secondary-button">Back to lobby</button>',{closable:false});$('cancel-queue').onclick=lobby;const ws=socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws`);connectTimer=setTimeout(()=>{if(socket===ws&&ws.readyState!==WebSocket.OPEN)networkError('The server is taking longer to respond. Try again shortly.')},20000);ws.onopen=()=>{clearTimeout(connectTimer);const p=profile.get(),o=ownAppearance();ws.send(JSON.stringify({type:'join',name:p.name,color:o.color,outfit:o.outfit,level,room}))};ws.onmessage=e=>{let s;try{s=JSON.parse(e.data)}catch{return}lastNetMessage=performance.now();if(s.type==='error')return networkError(s.message);if(s.type==='joined'){myId=s.id;return}if(s.type==='state')receiveState(s)};ws.onerror=()=>networkError('Could not connect. Check your internet connection and try again.');ws.onclose=()=>{if(online&&!lastResult)networkError('Your connection was interrupted. Your saved progress is safe.')}}
function networkError(message){disconnect();mode='results';clearInput();$('touch').hidden=true;$('countdown').hidden=true;modal(`<h2>Let’s reconnect.</h2><p>${escapeHTML(message)}</p><button id="reconnect" class="primary-button">TRY AGAIN <span>↗</span></button><button id="network-home" class="secondary-button">Back to lobby</button>`);$('reconnect').onclick=()=>joinOnline(level);$('network-home').onclick=lobby}
function receiveState(s){if(!online||lastResult)return;const previous=network;network=s;const own=s.players.find(p=>p.id===myId);if(!own)return;if(s.level!==level){level=s.level;view.load(level)}Object.assign(player,own,{collected:s.self?.collected||[],remote:true,moving:Math.abs(player.z-own.z)>.01||Math.abs(player.x-own.x)>.01});worldTime=s.clock;time=s.time;player.id=myId;
 // A personal finish is terminal immediately. The room keeps running for others.
 if(own.finished){finish(true,{onlineFinish:true});return}if(s.phase==='complete'||own.eliminated){finish(false,{onlineFinish:true});return}
 mode=s.phase==='race'?'race':s.phase==='countdown'?'countdown':'waiting';$('online-status').textContent=`LIVE · ${s.humans} HUMAN${s.humans===1?'':'S'} · ROOM ${s.room}`;
 if(s.phase==='waiting'){if(previous?.phase!=='waiting'||!$('queue-count')){modal(`<span class="pill">LEVEL ${s.level} · LIVE MATCHMAKING</span><h2>Bring your crew.</h2><div class="room-code">${escapeHTML(s.room)}</div><p id="queue-count"></p><div class="queue-dots" id="queue-dots"></div><p>Invite friends with the link below. Empty slots fill with labeled bots at the start.</p><button id="invite" class="primary-button">COPY INVITE LINK <span>↗</span></button><button id="cancel-queue" class="secondary-button">Back to lobby</button>`,{closable:false});$('invite').onclick=async()=>{const url=new URL(location.href);url.search='?room='+s.room;try{await navigator.clipboard.writeText(url.href);$('invite').textContent='INVITE COPIED ✓'}catch{modal(`<h2>Your race invite</h2><div class="form-row"><label>Copy this link</label><input id="invite-url" readonly></div><button id="back-queue" class="primary-button">BACK <span>↗</span></button>`);$('invite-url').value=url.href;$('invite-url').select();$('back-queue').onclick=()=>{network=null;receiveState(s)}}};$('cancel-queue').onclick=lobby}if($('queue-count'))$('queue-count').textContent=`${s.humans} connected · Race begins in ${Math.ceil(s.remaining)}s`;if($('queue-dots'))$('queue-dots').innerHTML=Array.from({length:16},(_,i)=>`<i class="${i<s.humans?'connected':''}"></i>`).join('')}
 if(s.phase==='countdown'){if($('modal').open)$('modal').close();$('countdown').hidden=false;$('countdown').textContent=Math.max(1,Math.ceil(s.remaining));$('level-intro').hidden=false;$('level-intro').textContent=`LEVEL ${level} / 50 · ${levelById(level).name.toUpperCase()}`}
 if(s.phase==='race'&&previous?.phase!=='race'){$('modal').close();$('countdown').hidden=true;$('level-intro').hidden=true;clearInput();tone(880,.2)}$('touch').hidden=s.phase!=='race'||!matchMedia('(pointer:coarse)').matches;
}
function sendInput(dt){netElapsed+=dt;if(netElapsed<.045||socket?.readyState!==WebSocket.OPEN)return;netElapsed=0;socket.send(JSON.stringify({type:'input',...readInput(),jump:!$('modal').open&&queuedJump,dive:!$('modal').open&&queuedDive}));queuedJump=false;queuedDive=false}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.06,Math.max(0,(now-last)/1000));last=now;frameCount++;performanceTime+=dt;
 if(mode==='lobby')worldTime+=dt;if(mode==='countdown'&&!online){countTime-=dt;const n=Math.ceil(countTime);if(n>0){if($('countdown').textContent!==String(n)){tone(440,.08);$('countdown').textContent=n}}else{mode='race';$('countdown').hidden=true;$('level-intro').hidden=true;tone(880,.2)}}
 if(mode==='race'&&!online){accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps++<5&&mode==='race'){soloStep(1/60);accumulator-=1/60}}
 if(online){sendInput(dt);if(lastNetMessage&&now-lastNetMessage>10000){networkError('The race stopped responding. Join a new race to continue.')}}
 if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('race-message').style.opacity=0}hitFlash=Math.max(0,hitFlash-dt);if(mode!=='lobby')syncHUD();const isLobby=mode==='lobby';let states;if(isLobby)states=[{...player,...ownAppearance(),id:'you'}];else if(online&&network)states=network.players.map(p=>({...p,...(p.id===myId?player:{}),moving:mode==='race',remote:true}));else states=[player,...bots];
 view.render({t:worldTime,dt,lobby:isLobby,focus:player,states,collected:player.collected,shake:hitFlash});
 if(performanceTime>12&&profile.get().quality==='auto'&&frameCount/performanceTime<23){view.quality('low');performanceTime=-1e9}
}
resetRun();syncLobby();requestAnimationFrame(frame);$('loading').hidden=true;
$('play').onclick=()=>profile.get().tutorial?intro(level):tutorial(()=>intro(level));$('online').onclick=()=>profile.get().tutorial?intro(level,true):tutorial(()=>intro(level,true));$('nav-play').onclick=lobby;$('nav-tour').onclick=()=>showMap();$('open-map').onclick=()=>showMap();$('nav-locker').onclick=showCrew;$('customize').onclick=showCrew;$('edit-profile').onclick=showProfile;$('settings').onclick=showSettings;$('help').onclick=showHelp;$('pause').onclick=pause;
$('close-modal').onclick=()=>{if(mode==='results')lobby();else closeModal()};$('modal').addEventListener('cancel',e=>{e.preventDefault();if(mode==='waiting')return;if(mode==='results')lobby();else closeModal()});
$('about').onclick=()=>modal('<span class="pill">BEAN DASH · WORLD TOUR</span><h2>One more run.</h2><p>50 increasingly challenging levels across five worlds. Real-time online races, solo adventures, coins, medals, and an unlockable crew. Free to play without an account.</p><p>Original game assets inspired by the colorful obstacles of Fall Guys, the streetwear runners of Subway Surfers, and the time-medal challenge of Trackmania.</p><p><a href="https://www.youtube.com/watch?v=fGy-x3H-nxU" target="_blank" rel="noopener">Subway Surfers official trailer ↗</a><br><a href="https://fallguys.com/en-US/seasons/season-3" target="_blank" rel="noopener">Fall Guys obstacle references ↗</a><br><a href="https://wiki.trackmania.io/en/game-client/main-menu" target="_blank" rel="noopener">Trackmania campaign references ↗</a></p><p>Guest saves stay in this browser. Live race rooms are temporary. This game is not affiliated with those titles or their creators.</p>');
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&['race','countdown'].includes(mode))e.preventDefault();if(e.code==='Escape'){e.preventDefault();if($('modal').open){if(mode==='results')lobby();else if(mode!=='waiting')closeModal()}else pause();return}if(!e.repeat&&mode==='race'){if(e.code==='Space')queuedJump=true;if(e.code==='ShiftLeft'||e.code==='ShiftRight')queuedDive=true}keys.add(e.code)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(!online&&['race','countdown'].includes(mode))pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(!online&&['race','countdown'].includes(mode))pause()}});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);if(b.dataset.key==='Space')queuedJump=true;if(b.dataset.key==='ShiftLeft')queuedDive=true});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key))});
window.beanDash={getState:()=>({mode,level,time,online,room:network?.room,phase:network?.phase,finished:player.finished,player:{x:player.x,y:player.y,z:player.z,checkpoint:player.cp},distance:levelById(level).distance,guest:profile.get().id})};
const invite=new URLSearchParams(location.search).get('room');if(invite&&/^[A-Fa-f0-9]{6}$/.test(invite))joinOnline(1,invite);
